CREATE TABLE IF NOT EXISTS deployment_environments (project_id TEXT NOT NULL, environment TEXT NOT NULL, configuration JSONB NOT NULL DEFAULT '{}'::jsonb, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(project_id,environment));
CREATE TABLE IF NOT EXISTS deployment_services (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, name TEXT NOT NULL, runtime_id TEXT NOT NULL, process_identity TEXT, protocol TEXT NOT NULL, host TEXT NOT NULL, port INTEGER NOT NULL, health_endpoint TEXT, status TEXT NOT NULL, environment TEXT NOT NULL, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS deployment_ports (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, runtime_id TEXT NOT NULL, service_id TEXT REFERENCES deployment_services(id) ON DELETE SET NULL, internal_port INTEGER NOT NULL, external_port INTEGER NOT NULL, protocol TEXT NOT NULL, exposure_mode TEXT NOT NULL, status TEXT NOT NULL, health TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, UNIQUE(protocol,external_port));
CREATE TABLE IF NOT EXISTS deployment_previews (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, service_id TEXT NOT NULL REFERENCES deployment_services(id) ON DELETE CASCADE, environment TEXT NOT NULL, hostname TEXT NOT NULL UNIQUE, url TEXT NOT NULL, status TEXT NOT NULL, access_policy TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS deployment_domains (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, hostname TEXT NOT NULL UNIQUE, service_id TEXT REFERENCES deployment_services(id) ON DELETE SET NULL, environment TEXT NOT NULL, status TEXT NOT NULL, tls_status TEXT NOT NULL, verification_status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS deployment_certificates (id TEXT PRIMARY KEY, domain_id TEXT NOT NULL REFERENCES deployment_domains(id) ON DELETE CASCADE, status TEXT NOT NULL, issuer TEXT, expires_at TIMESTAMPTZ, error TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS deployment_releases (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, git_revision TEXT NOT NULL, artifact_references JSONB NOT NULL DEFAULT '[]'::jsonb, build_metadata JSONB NOT NULL DEFAULT '{}'::jsonb, environment TEXT NOT NULL, configuration_version TEXT, verification_run_id TEXT, status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS deployments (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, environment TEXT NOT NULL, version TEXT NOT NULL, source_revision TEXT NOT NULL, runtime_target TEXT NOT NULL, release_id TEXT REFERENCES deployment_releases(id), strategy TEXT NOT NULL, status TEXT NOT NULL, health_status TEXT, failure_reason TEXT, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL, started_at TIMESTAMPTZ, completed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS deployment_events (id BIGSERIAL PRIMARY KEY, deployment_id TEXT REFERENCES deployments(id) ON DELETE CASCADE, project_id TEXT NOT NULL, type TEXT NOT NULL, payload JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS deployment_health_checks (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, service_id TEXT REFERENCES deployment_services(id) ON DELETE CASCADE, runtime_id TEXT NOT NULL, type TEXT NOT NULL, target TEXT NOT NULL, timeout_ms BIGINT NOT NULL, interval_ms BIGINT NOT NULL, retries INTEGER NOT NULL, failure_threshold INTEGER NOT NULL, success_threshold INTEGER NOT NULL, status TEXT NOT NULL, last_error TEXT, checked_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS deployment_snapshots (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, kind TEXT NOT NULL, reference TEXT NOT NULL, source TEXT NOT NULL, status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
